import { Guide } from "@/lib/guide";
import googleWorkspace from "./google-workspace.json";
import hubspot from "./hubspot.json";
import microsoft365 from "./microsoft-365.json";
import notion from "./notion.json";
import salesforce from "./salesforce.json";
import slack from "./slack.json";
import strava from "./strava.json";

// Human-reviewed guides, validated against the schema at load so a bad edit fails loudly.
// google-workspace was written by hand from official sources; the others were generated by the
// agent and corrected after independent verification (see scripts/curate/).
const RAW: Record<string, unknown> = {
  "google-workspace": googleWorkspace,
  "microsoft-365": microsoft365,
  slack,
  salesforce,
  hubspot,
  notion,
  strava,
};

export const CURATED: Record<string, Guide> = Object.fromEntries(Object.entries(RAW).map(([slug, g]) => [slug, Guide.parse(g)]));
